import json,re,hashlib,difflib,collections,os
from pathlib import Path
R=Path(__file__).resolve().parent.parent;E=R/'server-final-evidence';S=R/'source'
base=json.loads((E/'baseline.json').read_text());before=json.loads((E/'before-sha256.json').read_text())
after={str(p.relative_to(S)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted((S/'server').rglob('*')) if p.is_file()}
(E/'after-sha256.json').write_text(json.dumps(after,indent=2))
changed=[n for n,v in after.items() if before.get(n)!=v]
diff=''.join(''.join(difflib.unified_diff(base.get(n,'').splitlines(keepends=True),(S/n).read_text().splitlines(keepends=True),fromfile='before/'+n,tofile='after/'+n)) for n in changed if n.endswith('.go'))
(E/'server-final.patch').write_text(diff)
cjk=re.compile('[\u3400-\u9fff]');token=re.compile(r'//[^\n]*|/\*.*?\*/|"(?:[^"\\]|\\.)*"|`[^`]*`',re.S)
rows=[]
for p in sorted((S/'server').rglob('*')):
 if not p.is_file() or p.suffix not in ('.go','.json'):continue
 text=p.read_text();n=str(p.relative_to(S));kinds={}
 if p.suffix=='.go':
  for m in token.finditer(text):
   if not cjk.search(m[0]):continue
   start=text[:m.start()].count('\n')+1
   for j,l in enumerate(m[0].splitlines()):
    if cjk.search(l):kinds.setdefault(start+j,[]).append('comment' if m[0].startswith(('/',)) else 'literal')
 for i,l in enumerate(text.splitlines(),1):
  if not cjk.search(l):continue
  if kinds.get(i)==['comment']:cl='untranslated_comment'
  elif n=='server/chat_mentions.go':cl='functional_exception_legacy_mention_aliases'
  elif n=='server/conversations.go' and '新对话' in l:cl='functional_exception_persisted_legacy_title'
  elif n=='server/logsink.go':cl='functional_exception_multilingual_log_classification'
  elif n=='server/server.go' and ('HasPrefix' in l or 'TrimPrefix' in l):cl='functional_exception_multilingual_input_recognition'
  elif n=='server/orchestration.go' and 694<=i<=696:cl='functional_exception_exact_legacy_prompt_migration_sentinel'
  elif n=='server/runtime_english_test.go':cl='functional_exception_multilingual_and_legacy_regression_fixture'
  elif n=='server/testdata/english_mentions.json':cl='functional_exception_multilingual_mention_fixture'
  elif n.endswith('_test.go'):cl='test_fixture_or_assertion_review_required_not_all_exempt'
  elif 'literal' not in kinds.get(i,[]):cl='untranslated_comment_or_documentation_reference'
  else:cl='untranslated_runtime_prose_or_prompt_review_required'
  rows.append({'path':n,'line':i,'classification':cl,'text':l})
(E/'remaining-nonenglish.json').write_text(json.dumps(rows,indent=2,ensure_ascii=False))
counts=dict(collections.Counter(r['classification'] for r in rows));perfile=dict(sorted(collections.Counter(r['path'] for r in rows).items()))
tests=json.loads((E/'final-pinned.json').read_text());required=['TestRuntimeEnglishApprovalCompatibility','TestRuntimeEnglishTaskContext','TestRuntimeEnglishValidation','TestRuntimeEnglishToolDescriptions','TestRuntimeEnglishTruncationPreservesUnicode','TestChatMentionEnglishLegacyCompatibility','TestChatMentionFrontendGeneratedTokens','TestMergeAllRunsWritesTaskGoalOnce','TestMergeAllRunsGroupsInterleavedTasks','TestUploadSkillRejectsTraversal']
assert all(any(x['name']==n and x['action']=='pass' for x in tests['tests']) for n in required)
# Exact sentinel, mention aliases, and recognition expressions retained from handoff.
legacy=lambda s: re.search(r'const reporterToolCallMessageV1 = .*?\n\n',s,re.S)[0]
assert legacy(base['server/orchestration.go'])==legacy((S/'server/orchestration.go').read_text())
contract=json.loads((E/'literal-contract-check.json').read_text());struct=json.loads((E/'token-structure-check.json').read_text());assert all(struct.values()) and all(all(v.values()) for v in contract.values())
report={'status':'PARTIAL: generated runtime/API/default prose translated; comments and test prose remain','changed_path_count':len(changed),'changed_paths':changed,'tests':tests,'required_test_names_verified':required,'skipped_tests':[x['name'] for x in tests['tests'] if x['action']=='skip'],'remaining_nonenglish':{'line_count':len(rows),'file_count':len(perfile),'classification_counts':counts,'per_file':perfile,'inventory':'remaining-nonenglish.json','limitations':'CJK lexical scan is not a proof of every language. Test review category includes purposeful evidence fixtures and untranslated names/assertions, not a blanket exemption.'},'api_contract':{'go_scanner_nonstring_noncomment_structure_unchanged':all(struct.values()),'production_files_checked':len(struct),"json_tags_map_keys_routes_regexes_preserved":True,'sql_structure_preserved':True,'sql_receipt':'sql-contract-check.json','legacy_reporter_migration_sentinel_exact':True,'approval_compatibility':'Server activityDTO transparently preserves both [Model]/[模型] and English/legacy approval summaries, verified with production DTO entrypoint. DB classification/producer behavior remains peer-owned and real approval HTTP tests skip without PostgreSQL.','mention_compatibility':'All nine English and legacy aliases passed actual production parser tests, including frontend-generated fixtures.','reporter_context':'Task: #<id> header now matches agent prompt while retaining user description/goal verbatim; merge grouping and bounds regressions pass.'},'tdd':{'runtime_red':'red.jsonl: 3 top-level failures and 10 subtest failures before translations; same entrypoints green','task_context_red':'context-red.jsonl: Task: # prefix assertion failed before header change','approval_dto':'Existing-behavior regression added after translations; immediately passed, not claimed as new RED','broader_translation':'Other prose/comment changes are batch translation edits, not individually test-first','retained_failed_regression':'focused.jsonl has two stale merge assertions for prior output decoration. Repaired exact generated-output assertions without weakening event counts, user evidence, grouping or bounds.'},'evidence':{'before':'before-sha256.json','after':'after-sha256.json','patch':'server-final.patch','baseline':'baseline.json','raw_final':'final-pinned.jsonl','contract':'token-structure-check.json and literal-contract-check.json','format':'gofmt.json'},'limits':['Only server source and NEW server-final-evidence written; prior server-evidence untouched.','No PostgreSQL startup, network/package installation, listeners, model calls or whole-app build. PostgreSQL-dependent skips are not passes.','Cached offline toolchain compiled the actual server import graph successfully. Concurrent peer agent edits mean this is focused server evidence, not coherent whole-application qualification.','Saved/custom user prompts are not rewritten; exact legacy migration sentinel retained. Existing migrations and admission/budget/security logic unchanged.','Remaining untranslated comments and test prose require another pass. No claim that the whole server is English.'],'lessons_handoff':['Exact persisted default-prompt sentinel strings are compatibility data; restore them byte-for-byte after any phrase translations.','Treat approval reasons and summaries as opaque evidence in server DTOs; peer DB classifiers must retain both producer generations.','Compare Go scanner structure and literal contracts alongside executed regressions when translating large source surfaces.'],'disk_free_bytes':os.statvfs(E).f_bavail*os.statvfs(E).f_frsize}
(E/'report.json').write_text(json.dumps(report,indent=2,ensure_ascii=False))
review=f'''# Server final English continuation — partial completion\n\nTranslated remaining generated runtime/API errors, default labels, tool descriptions/schemas, reporter and scheduler guidance, logs, seed prose, and selected comments. Preserved saved user prompts and exact legacy recognition strings.\n\nChanged **{len(changed)} server paths** relative to the handoff snapshot. Actual offline Go final run: top-level **{tests['top_level']}**; subtests **{tests['subtests']}**. Required regression names verified. PostgreSQL-dependent tests skipped; no database was started. Raw: `final-pinned.jsonl`.\n\nAll {len(struct)} production files retained their exact non-string/non-comment Go token structure. JSON tags, map keys, routes and regex expressions match the handoff. Reporter task context now uses `Task: #<id>` and retains user evidence. Both English/legacy mention parser and opaque approval DTO compatibility pass. Real DB approval HTTP coverage is skipped, not qualified.\n\n## Remaining untranslated scope\nCJK-bearing lines: **{len(rows)} across {len(perfile)} paths**. This includes functional multilingual exceptions; do not call all of it untranslated. Detailed exact classification and every path/line/text: `remaining-nonenglish.json`.\n\n'''+''.join(f'- {k}: {v}\n' for k,v in sorted(counts.items()))+'\n## Remaining by path\n'+''.join(f'- `{k}`: {v}\n' for k,v in perfile.items())+'''\n## Limits and receipts\n- Full app/frontend/model/DB qualification was not run; another worker is changing agent sources. Focused server compilation succeeded against the imported tree at execution time.\n- Previous receipts are untouched. New baseline/hashes, exact patch, failed RED/regression streams, GREEN, format and contract receipts are in this directory.\n- Initial source-file tool lint runs outside the Go module reported setup errors; these are not the test result. Actual cached offline package tests compiled and ran successfully.\n- Two stale merge-output assertions were corrected to exact English formatting; event counts, grouping, retained evidence, and bounds were preserved.\n- Lessons are handoff only; no global skill/profile changes.\n'''
(E/'REVIEW.md').write_text(review);print(json.dumps({'changed':len(changed),'remaining_lines':len(rows),'remaining_files':len(perfile),'classifications':counts,'tests':tests['top_level'],'subtests':tests['subtests']},indent=2))
